CREATE TABLE IF NOT EXISTS `UserProfile` (`ownerUid` TEXT NOT NULL, `zoneId` TEXT NOT NULL, `activeStartMinute` INTEGER NOT NULL, `activeEndMinute` INTEGER NOT NULL, `busyUntilAt` INTEGER, PRIMARY KEY(`ownerUid`))
CREATE TABLE IF NOT EXISTS `Task` (`id` TEXT NOT NULL, `ownerUid` TEXT NOT NULL, `title` TEXT NOT NULL, `course` TEXT NOT NULL, `description` TEXT NOT NULL, `deadlineAt` INTEGER NOT NULL, `difficultyScore` INTEGER NOT NULL, `initialEstimatedMinutes` INTEGER NOT NULL, `remainingMinutes` INTEGER NOT NULL, `analysisSource` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `completedAt` INTEGER, PRIMARY KEY(`id`), FOREIGN KEY(`ownerUid`) REFERENCES `UserProfile`(`ownerUid`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_Task_ownerUid_status_completedAt` ON `Task` (`ownerUid`, `status`, `completedAt`)
CREATE UNIQUE INDEX IF NOT EXISTS `index_Task_id_ownerUid` ON `Task` (`id`, `ownerUid`)
CREATE TABLE IF NOT EXISTS `FixedSchedule` (`id` TEXT NOT NULL, `ownerUid` TEXT NOT NULL, `label` TEXT NOT NULL, `kind` TEXT NOT NULL, `dayOfWeek` INTEGER NOT NULL, `startMinute` INTEGER NOT NULL, `endMinute` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`ownerUid`) REFERENCES `UserProfile`(`ownerUid`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_FixedSchedule_ownerUid_dayOfWeek` ON `FixedSchedule` (`ownerUid`, `dayOfWeek`)
CREATE TABLE IF NOT EXISTS `WorkSession` (`id` TEXT NOT NULL, `taskId` TEXT NOT NULL, `ownerUid` TEXT NOT NULL, `state` TEXT NOT NULL, `plannedStartAt` INTEGER NOT NULL, `plannedEndAt` INTEGER NOT NULL, `plannedMinutes` INTEGER NOT NULL, `startedAt` INTEGER, `endedAt` INTEGER, `actualWorkMs` INTEGER, `timerBootId` TEXT, `activeSinceElapsedMs` INTEGER, `cutoffElapsedMs` INTEGER, `lastObservedWorkMs` INTEGER, `revision` INTEGER NOT NULL, `pausedRemainingMs` INTEGER, `pausedFromState` TEXT, `workBeforeSegmentMs` INTEGER, `continuousWorkBeforeSegmentMs` INTEGER, `lastObservedAt` INTEGER, PRIMARY KEY(`id`), FOREIGN KEY(`taskId`, `ownerUid`) REFERENCES `Task`(`id`, `ownerUid`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_WorkSession_ownerUid_state_plannedStartAt` ON `WorkSession` (`ownerUid`, `state`, `plannedStartAt`)
CREATE INDEX IF NOT EXISTS `index_WorkSession_taskId_ownerUid` ON `WorkSession` (`taskId`, `ownerUid`)
CREATE TABLE IF NOT EXISTS `CalendarEvent` (`id` TEXT NOT NULL, `ownerUid` TEXT NOT NULL, `title` TEXT NOT NULL, `startEpochDay` INTEGER NOT NULL, `endEpochDay` INTEGER NOT NULL, `startMinute` INTEGER, `description` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`ownerUid`) REFERENCES `UserProfile`(`ownerUid`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_CalendarEvent_ownerUid_startEpochDay` ON `CalendarEvent` (`ownerUid`, `startEpochDay`)
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
